12	     * A word longer than width is placed on its own line unchanged. Runs of whitespace collapse to one space.
13	     * Existing blank-line paragraph breaks (an empty line) are kept as one empty line in the output.
14	     */
15	    public static List<String> wrap(String text, int width) {
16	        if (width < 1) throw new IllegalArgumentException("width must be >= 1");
17	        List<String> lines = new ArrayList<>();
18	        for (String para : text.split("\n\\s*\n", -1)) {
19	            if (!lines.isEmpty()) lines.add("");
20	            StringBuilder cur = new StringBuilder();
21	            for (String word : para.trim().split("\\s+")) {
22	                if (word.isEmpty()) continue;
23	                if (cur.length() == 0) {
24	                    cur.append(word);
25	                } else if (cur.length() + 1 + word.length() < width) {
26	                    cur.append(' ').append(word);
